System.register("chunks:///_virtual/vi.ts",["cc"],(function(t){var n;return{setters:[function(t){n=t.cclegacy}],execute:function(){n._RF.push({},"05cc6txi1xIToK5tHdAChfv","vi",void 0);t("LOCALE_VI",{CLIENT_CURRENENCY_SYMBOL:"₫",System_Warning_Server_ExpiredLink:"Liên kết trò chơi này đã hết hạn.",System_Warning_Server_InvalidRequest:"Yêu cầu không hợp lệ.",UI_CONTROL_PANEL_BET:"CƯỢC",UI_CONTROL_PANEL_CREDIT:"TÍN DỤNG",UI_CONTROL_PANEL_CURRENCY_GUIDE:"NHẤP ĐỂ CHUYỂN GIỮA\nCHẾ ĐỘ XEM TIỀN VÀ XU",UI_CONTROL_PANEL_GUIDE_1:"CHÚC MAY MẮN!",UI_CONTROL_PANEL_GUIDE_2:"ĐẶT CƯỢC CỦA BẠN!",UI_CONTROL_PANEL_GUIDE_3:"QUAY ĐỂ THẮNG!",UI_CONTROL_PANEL_TEXT_AUTO_SPIN:"SỐ AUTO SPIN CÒN LẠI",UI_CONTROL_PANEL_TEXT_FREE_SPIN:"SỐ FREE SPIN CÒN LẠI",UI_CONTROL_PANEL_TEXT_FREE_SPIN_ACCUMULATED:"TỔNG TIỀN THẮNG",UI_CONTROL_PANEL_TEXT_PAY_WIN:"THẮNG",UI_POPUP_AUTOPLAY_NUMBER:"SỐ LƯỢNG AUTOSPIN",UI_POPUP_AUTOPLAY_QUICK:"QUAY NHANH",UI_POPUP_AUTOPLAY_START:"BẮT ĐẦU AUTOPLAY ({Count})",UI_POPUP_AUTOPLAY_TITLE:"CÀI ĐẶT AUTOSPIN",UI_POPUP_AUTOPLAY_TURBO:"QUAY TURBO",UI_POPUP_BET_COIN_LINE:"CƯỢC",UI_POPUP_BET_COIN_VALUE:"GIÁ TRỊ XU",UI_POPUP_BET_MAX:"CƯỢC TỐI ĐA",UI_POPUP_BET_TITLE:"HỆ SỐ NHÂN CƯỢC",UI_POPUP_BET_TOTAL_BET:"TỔNG CƯỢC",UI_POPUP_BUYBONUS_ACTIVATE:"KÍCH HOẠT",UI_POPUP_BUYBONUS_BET_GUIDE:"TỔNG CƯỢC",UI_POPUP_BUYBONUS_BUY:"MUA",UI_POPUP_BUYBONUS_CANCEL:"HỦY",UI_POPUP_BUYBONUS_OK:"OK",UI_POPUP_BUYBONUS_TITLE:"MUA BONUS",UI_POPUP_BUYBONUS_MIGHTY_TITLE:"MIGHTY FEATURE",UI_POPUP_BUYBONUS_MIGHTY_DESC:"Mua Mighty Feature.\nChơi trên lưới 5 x 3.",UI_POPUP_BUYBONUS_MEGA_TITLE:"MEGA FEATURE",UI_POPUP_BUYBONUS_MEGA_DESC:"Mua Mega Feature.\nChơi trên lưới 5 x 4.",UI_POPUP_BUYBONUS_SUPER_TITLE:"SUPER FEATURE",UI_POPUP_BUYBONUS_SUPER_DESC:"Mua Super Feature.\nChơi trên lưới 5 x 5.",UI_POPUP_PAY_PAGE1_CONTENTS1:"Trước khi reel của trò chơi cơ bản bắt đầu quay, một số vị trí được thay thế bằng bất kỳ biểu tượng nào ngoại trừ  <img src = '11' height=50 offset=-8 />  và  <img src = '13' height=50 offset=-8 /> . \nChỉ phần thắng cao nhất được trả cho mỗi tổ hợp thắng.\nCác tổ hợp thắng chỉ có thể chứa một biểu tượng từ mỗi reel liền kề, bắt đầu từ reel ngoài cùng bên trái.\nCác biểu tượng giống nhau, hoặc biểu tượng thay thế, trên cùng một reel không thuộc cùng một tổ hợp thắng, nhưng có thể tạo ra các tổ hợp thắng riêng biệt.\nTất cả phần thắng theo ways đều được nhân với hệ số nhân cược.",UI_POPUP_PAY_PAGE1_TITLE1:"TRẢ THƯỞNG",UI_POPUP_PAY_PAGE2_CONTENTS1:"xuất hiện trên reel 2, 3 và 4 và là WILD cho tất cả biểu tượng xuất hiện trong trò chơi cơ bản ngoại trừ  <img src = '13' height=50 offset=20 /> .",UI_POPUP_PAY_PAGE2_CONTENTS2:"Trong trò chơi cơ bản, mỗi  <img src = '13' height=50 offset=20 />  sẽ hiển thị giá trị tín dụng từ 10% đến 500% tổng số tiền cược.",UI_POPUP_PAY_PAGE2_TITLE1:"WILD/TRAIL",UI_POPUP_PAY_PAGE2_TITLE2:"SHOU BONUS",UI_POPUP_PAY_PAGE3_CONTENTS1:"Bất kể số lượng <img src = '13' height=50 offset=20/>  thu thập được từ kết quả reel, Feature Game có thể được kích hoạt ngẫu nhiên. \nNếu một sự kiện may mắn xảy ra, một số biểu tượng xuất hiện trên reel sẽ biến đổi thành \n<img src = '13' height=50 offset=20/>  cho đến khi đạt được yêu cầu tối thiểu 6 Shou Symbols để vào Feature.\n<img src = '13' height=50 offset=20/>  đã biến đổi sẽ được gán Credit Value dựa trên cơ hội ngẫu nhiên, sau đó màn hình Feature Select sẽ được hiển thị.\nSự kiện may mắn này có thể xảy ra ngay cả khi không có <img src = '13' height=50 offset=20/>  nào xuất hiện trong kết quả reel, và kết quả được xác định độc lập trên mỗi lượt quay.",UI_POPUP_PAY_PAGE3_TITLE1:"MAY MẮN BẤT NGỜ",UI_POPUP_PAY_PAGE4_CONTENTS1:"6 hoặc nhiều   <img src = '13' height=50 offset=0/>  rải rác trong trò chơi cơ bản sẽ trao tổng các giá trị hiển thị trên   <img src = '13' height=50 offset=0/>  và Feature Selection.\nNếu có ít nhất 1 vị trí không chứa  <img src = '13' height=50 offset=0/>, thì Feature Selection cung cấp lựa chọn Free Games Bonus hoặc Top Up Bonus.\n <img src = '13' height=50 offset=0/>  và  <img src = '11' height=50 offset=0/> không xuất hiện trong Free Games Bonus.\n",UI_POPUP_PAY_PAGE4_CONTENTS2:"<color=yellow>5 High Symbols: Một Free Games Bonus với giá trị 128 <img src = '10' height=50 offset=5/> , 118 <img src = '9' height=50 offset=5/> , 108 <img src = '8' height=50 offset=5/> , 98 <img src = '7' height=50 offset=5/> , hoặc 88 <img src = '6' height=50 offset=5/> , hoặc một Top Up Bonus với giá trị 88 <img src = '6' height=50 offset=5/>  được trao. <color=white>",UI_POPUP_PAY_PAGE4_CONTENTS3:"Chỉ biểu tượng được chọn,<img src = '5' height=70 offset=-5/>  ,<img src = '4' height=70 offset=-5/>  ,<img src = '3' height=70 offset=-5/>  , <img src = '2' height=70 offset=-5/>  ,<img src = '1' height=70 offset=-5/>  ,<img src = '0' height=70 offset=-5/>  , và  <img src = '13' height=50 offset=0/>  sẽ xuất hiện trong Free Games Bonus.",UI_POPUP_PAY_PAGE4_TITLE1:"LỰA CHỌN TÍNH NĂNG",UI_POPUP_PAY_PAGE5_CONTENTS1:"Trao 6 free game.\nNếu có ít nhất 1  <img src = '12' height=50 offset= 15/>  xuất hiện trên màn hình, thì tổng tất cả giá trị hiển thị trên các biểu tượng kích hoạt được trao cho mỗi  <img src = '12' height=50 offset= 15/>  trên màn hình.\nNgoài ra, nếu Top Up Bonus có sẵn trong Feature Selection, giá trị hiển thị trên đồng hồ Fortune Grand Jackpot có thể được trao.\nMột bộ reel khác được sử dụng trong Free Games Bonus. Các tổ hợp thắng cho những reel này giống hệt trò chơi cơ bản trừ khi có quy định khác.\n<img src = '12' height=50 offset= 15/>  chỉ xuất hiện trên reel 2–4 và là WILD cho tất cả biểu tượng ngoại trừ  <img src = '13' height=50 offset= 15/>  .\n“Shou Bonus” trong Free Games Bonus là tổng phần thưởng tích lũy của tất cả  <img src = '12' height=50 offset= 15/>  và tổng tất cả giá trị hiển thị trên mỗi  <img src = '13' height=50 offset= 15/>  trong trò chơi cơ bản.\n“Shou Bonus” không bao gồm bất kỳ jackpot nào được trao.",UI_POPUP_PAY_PAGE5_TITLE1:"FREE GAMES BONUS",UI_POPUP_PAY_PAGE6_CONTENTS1:"Trao 6 lượt quay.\nTất cả    <img src = '13' height=50 offset= 5/>    xuất hiện trên lượt quay kích hoạt được giữ lại trong suốt bonus.\nNếu 1 hoặc nhiều    <img src = '12' height=50 offset= 5/>    rơi trên màn hình, mỗi    <img src = '12' height=50 offset= 5/>    sẽ hiển thị tổng tất cả giá trị tín dụng hiển thị trên các biểu tượng kích hoạt.\nSau khi tất cả    <img src = '12' height=50 offset= 5/>    được đánh giá, mỗi    <img src = '14' height=50 offset= 5/>    rơi trên màn hình ở lượt quay hiện tại được đánh giá lần lượt từng cái.\n  <img src = '14' height=50 offset= 5/>    hiển thị tổng tất cả giá trị tín dụng hiện đang hiển thị trên các vị trí được giữ.\nMỗi    <img src = '12' height=50 offset= 5/>    và    <img src = '14' height=50 offset= 5/>    rơi xuống sẽ được giữ cho đến khi kết thúc bonus.\nMỗi lượt quay, nếu số lượt quay đã chơi là 12 hoặc ít hơn, “+1 Spin” có thể xuất hiện ở một vị trí ngẫu nhiên không được giữ.\n“+1 Spin” trao thêm 1 lượt quay.\nNếu tất cả 15 vị trí được giữ, giá trị hiển thị trong đồng hồ Grand Jackpot được trao.\nCác lượt quay còn lại chỉ được chơi nếu có ít nhất 1 vị trí không được bao phủ bởi    <img src = '13' height=50 offset= 5/>   ,    <img src = '12' height=50 offset= 5/>   , hoặc    <img src = '14' height=50 offset= 5/>   .\nTất cả biểu tượng ngoài “+1 Spin”,    <img src = '12' height=50 offset= 5/>   , và    <img src = '14' height=50 offset= 5/>    xuất hiện trên reel sẽ bị làm xám và không được đánh giá.\nMột bộ reel khác được sử dụng trong Top Up Bonus.\n  <img src = '13' height=50 offset= 5/>    không xuất hiện trên reel trong Top Up Bonus. Lượt quay bonus không trao bonus bổ sung.",UI_POPUP_PAY_PAGE6_TITLE1:"TOP UP BONUS",UI_POPUP_PAY_PAGE7_CONTENTS1:"Jackpot Bonus có thể được kích hoạt nếu 1 hoặc nhiều  <img src = '11' height=50 offset=10/>  rơi trên màn hình trong trò chơi cơ bản.\nMột vùng chọn với 12  <img src = '16' height=50 offset=10/> được hiển thị. Mỗi lần chọn sẽ tiết lộ một trong các giải thưởng có sẵn.\nCác giải thưởng có sẵn bao gồm Mini Jackpot, Minor Jackpot, Major Jackpot, và Grand Jackpot.\nViệc chọn tiếp tục cho đến khi 3 biểu tượng khớp nhau được tiết lộ, và giá trị hiển thị trong đồng hồ tương ứng được trao.\nViệc tích lũy xu trong bát làm tăng cơ hội kích hoạt Jackpot Bonus.",UI_POPUP_PAY_PAGE7_TITLE1:"JACKPOT BONUS",UI_POPUP_PAY_PAGE8_CONTENTS1:"Nếu cùng một biểu tượng xuất hiện ít nhất một lần trên mỗi reel và có 3 biểu tượng trở lên liên tiếp từ trái sang phải, sẽ tạo thành một phần thắng.\nTất cả số tiền thắng được nhân với mức cược cơ bản.\nTất cả giá trị được hiển thị dưới dạng tiền thắng xu thực tế.\nKhi thắng với nhiều biểu tượng cùng lúc, tất cả số tiền thắng được cộng lại và trả thành tổng tiền thắng.\nTiền thắng từ feature được trao cho người chơi sau khi feature kết thúc.\nTổng tiền thắng từ feature được ghi vào lịch sử dưới dạng tiền thắng tích lũy của toàn bộ chu kỳ.\nTiền thắng jackpot kiếm được trong feature được ghi vào lịch sử.\nPhím SPACE và ENTER trên bàn phím có thể được dùng để bắt đầu hoặc dừng lượt quay.\n<color=#fff71f>RTP lý thuyết của trò chơi này là 95.81%. </color>\nTrong trường hợp trục trặc, tất cả cược và trả thưởng đều vô hiệu.\nReturn to Player (RTP) của trò chơi được đảm bảo đạt được trong vòng 100.000.000 vòng chơi.",UI_POPUP_PAY_PAGE8_TITLE1:"LUẬT CHƠI",UI_POPUP_SYSTEM_CANCEL:"HỦY",UI_POPUP_SYSTEM_CONFIRM:"XÁC NHẬN",UI_POPUP_SYSTEM_OK:"OK",UI_POPUP_SYSTEM_SETTING_BGM:"NHẠC NỀN",UI_POPUP_SYSTEM_SETTING_BGM_CONTENTS:"BẬT HOẶC TẮT \nNHẠC TRÒ CHƠI",UI_POPUP_SYSTEM_SETTING_BROADCAST:"PHÁT SÓNG",UI_POPUP_SYSTEM_SETTING_BROADCAST_CONTENTS:"BẬT HOẶC TẮT\nPHÁT SÓNG CHIẾN THẮNG TRÒ CHƠI",UI_POPUP_SYSTEM_SETTING_INTRO:"MÀN HÌNH GIỚI THIỆU",UI_POPUP_SYSTEM_SETTING_INTRO_CONTENTS:"HIỂN THỊ MÀN HÌNH GIỚI THIỆU TRƯỚC \nKHI BẮT ĐẦU TRÒ CHƠI",UI_POPUP_SYSTEM_SETTING_SFX:"HIỆU ỨNG ÂM THANH",UI_POPUP_SYSTEM_SETTING_SFX_CONTENTS:"BẬT HOẶC TẮT \nÂM THANH TRÒ CHƠI",UI_POPUP_SYSTEM_SETTING_TITLE:"CÀI ĐẶT HỆ THỐNG",UI_POPUP_SYSTEM_SETTING_VOLUME:"ÂM LƯỢNG",UI_POPUP_SYSTEM_TEXT1_MESSAGE:"Bạn đã bị ngắt kết nối khỏi máy chủ.",UI_POPUP_SYSTEM_TEXT1_TITLE:"Mạng",UI_POPUP_SYSTEM_TEXT2_MESSAGE:"Đăng nhập lại",UI_POPUP_SYSTEM_TEXT2_TITLE:"Mạng",UI_POPUP_SYSTEM_TEXT3_MESSAGE:"Vui lòng nạp tiền vào ví tiền mặt của bạn.\nNếu số dư không được cập nhật sau khi nạp,\nvui lòng làm mới ví tiền mặt của bạn.",UI_POPUP_SYSTEM_TEXT3_TITLE:"SỐ DƯ KHÔNG ĐỦ",UI_POPUP_SYSTEM_TEXT4_MESSAGE:"ID Biểu tượng sai.\nBạn đã bị ngắt kết nối khỏi máy chủ.",UI_POPUP_SYSTEM_TEXT4_TITLE:"Lỗi",UI_START_LOADING_1:"Lần khởi chạy đầu tiên có thể mất nhiều thời gian tải hơn.",UI_START_PAGE_1_DESCRIPTION:"KHÁM PHÁ CÁC TÍNH NĂNG VÀ BẤT NGỜ KHÁC NHAU!",UI_START_PAGE_2_DESCRIPTION:"CHẠM VÀO MỤC YÊU THÍCH, GIẢI PHÓNG NIỀM VUI!",UI_START_PAGE_3_DESCRIPTION:"KHÁM PHÁ SỰ PHẤN KHÍCH CỦA VẬN MAY BẤT NGỜ!",UI_START_PAGE_4_DESCRIPTION:"VÀO FREE SPINS VÀ ĐỐI MẶT VỚI HUYỀN THOẠI CỔ ĐẠI!",UI_START_PAGE_5_DESCRIPTION:"HÃY HY VỌNG NHIỀU BIỂU TƯỢNG ĐỎ VÀ XANH LÁ TỎA SÁNG HƠN!",UI_START_PAGE_6_DESCRIPTION:"KHÁM PHÁ NHỮNG DI VẬT CỔ ĐẠI QUA CON MẮT CỦA RA!",UI_START_PAGE_INFOMATION_ROLLING1:"Trong trò chơi bonus, <Sprite=10> vẫn ở trên bảng và tăng cơ hội thắng của bạn.                    Khi bạn thu thập <Sprite=11>, bạn nhận được phần thưởng biểu tượng.                    <Sprite=10> vẫn ở trên sân cho đến khi trò chơi kết thúc. Khi nó xếp chồng, hệ số nhân tăng lên.",UI_START_PAGE_INFOMATION_ROLLING2:"Mỗi khi  <Sprite=11>  xuất hiện, bạn được trao phần thưởng biểu tượng."});n._RF.pop()}}}));

